You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\section{Preliminaries}

Throughout the paper, $d$ always denotes the dimension of the ambient space $\mathbb{R}^d$ or $\mathbb{C}^d$, $\log$ without a base means the binary logarithm, $\ln=\log_e$ is the natural logarithm, and $\exp(f)=e^f$. 
We let $[d]$ denote the set $\{1,\ldots,d\}$ and $[d]-1$ denote the set $\{0,\ldots,d-1\}$.  
We denote by $\nrm{v}$ the $\ell_2$-norm of a vector, and by $\nrm{v}_p$ its $\ell_p$-norm.
For $A\in \mathbb{C}^{d\times d'}$, we define the spectral norm $\|A\|=\max\limits_{v\in\mathbb{C}^{d'}}\frac{\nrm{Av}}{\nrm{v}}$. For a set $S$, we define the indicator function $\mathds{1}_{S}$ as 
\begin{align*}
\mathds{1}_{S}(x)
	=\begin{cases}
		1 \text{ if } x\in S,\\
		0 \text{ otherwise.}
	\end{cases}
\end{align*}

The \emph{total variation distance} between probability distributions $P$ and $Q$ is defined as $d_{TV}(P,Q)=\sup_{A}P(A)-Q(A)$, where the supremum is over events $A$.
In particular, for discrete distributions we have $d_{TV}(P,Q)=\frac{1}{2}\sum_x |P(x)-Q(x)|$.
We say that two random variables are \emph{$\delta$-close} to each other if the total variation distance between their distributions is at most $\delta$. 

For us a projector is always a matrix $\Pi$ which is idempotent ($\Pi^2=\Pi$) and Hermitian ($\Pi^\dagger= \Pi$). For a subspace $S$ we denote the unique (orthogonal) projector to $S$ by $\Pi_S$.

\subsection{Concentration inequalities}

\begin{proposition}[Bennett-Bernstein Bound {\cite[Theorem 2.9 \& Eqn.\ 2.10]{stephane2013ConcIneqThIndep}}]\label{prop:BennettB}
	Let $X^{(i)}\colon i\in [n]$ be independent random variables with finite variance such that, for each $i$,  $X^{(i)}\leq b$ for some $b>0$ almost surely (i.e., this event has probability measure~1). Let 
	\begin{align*}
		S=\sum_{i=1}^n X^{(i)}-\mathbb{E}[X^{(i)}], \qquad v= \sum_{i=1}^n \mathbb{E}[(X^{(i)})^2],
	\end{align*}
	then for any $t>0$,
	\begin{align*}
		\Pr[S\geq t]
		\leq\exp\left(-\frac{v}{b^2}h\left(\frac{bt}{v}\right)\right)
		\leq\exp\left(-\frac{t^2}{2v+\frac{2}{3}bt}\right),
	\end{align*}	
	where $h(x)=(1+x)\ln(1+x)-x$.
\end{proposition}

\section{Time-efficient unbiased pure-state tomography}

\subsection{Pure-state tomography using conditional samples}\label{sec:qTomoCond}

\begin{lemma} \label{lem:UnbiasedTomoMeas}
	Suppose that $\psi\in \mathbb{C}^d$ has $\norm{\psi}_2\leq 1$, and we are given a copy of the state $\ket{\varphi'}:=\Big(\ket{+}\!\big(\ket{\bar{0}}\!\ket{\psi}+\ket{\bar{0}^\perp}\big)+\ket{-}\!\big(\ket{\bar{0}}\!\ket{\bar{\psi}}+\ket{\bar{0}'^\perp}\big)\Big)/\sqrt{2}$, where $\ket{\bar{0}}=\ket{0^a}$ for some $a\in\mathbb{N}$, $(\ketbra{\bar{0}}{\bar{0}}\otimes I)\ket{\bar{0}^\perp} = 0$, and $(\ketbra{\bar{0}}{\bar{0}}\otimes I)\ket{\bar{0}'^\perp} = 0$. If we measure $\ket{\varphi'}$ in the computational basis and denote by $X\in\{0,1\}^{2d}$ the indicator of the measurement outcomes $\ket{b}\ket{\bar{0}}\ket{i}$ (this $X$ is a weight-1 Boolean vector indexed by $(b,i)$ where $b\in \{0,1\}$ and $i\in[d]-1$), then the random vector $\psi'\in\mathbb{C}^d$ with coordinates
	\begin{align*}
		\psi'_i:=\frac{X_{0,i}-X_{1,i}}{|\bar{\psi}_i|}
	\end{align*}
	is an unbiased estimator of $\psi^{\Re}_i:=\mathrm{Re}\Big(\psi_i\frac{\bar{\psi}^*_i}{|\bar{\psi}_i|}\Big)$, with $\nrm{\psi'}_2\leq \frac{1}{\min\{|\bar{\psi}_i|\colon i\in [d]-1\}}$ with certainty, and covariance matrix $\mathrm{Cov}(\psi')=\frac{I}{2}+\mathrm{diag}\Big(\frac{|\psi_i|^2}{2|\bar{\psi_i|}^2}\Big)-\ketbra{\psi^{\Re}}{\psi^{\Re}}$.
\end{lemma}

By an analogous argument as in the proof of \Cref{lem:UnbiasedTomoMeas}, we can obtain an unbiased estimator of the imaginary parts $\psi^{\Im}_j:=\mathrm{Im}\left(\psi_j\frac{\bar{\psi}^*_j}{|\bar{\psi}_j|}\right)$ (with the same $\ell_2$-norm and covariance matrix gaurantee) by measuring $\ket{\varphi''}:=\left(\ket{+}\left(\ket{\bar{0}}\ket{\psi}+\ket{\bar{0}^\perp}\right)+i\ket{-}\left(\ket{\bar{0}}\ket{\bar{\psi}}+\ket{\bar{0}'^\perp}\right)\right)/\sqrt{2}$ in the computational basis.


********** END CONTEXT **********

