\begin{proof}
	We prove the first part of \Cref{thm:UnbiasedTomoMeas} first. Let us define the random vectors $\psi',\psi''\in\mathbb{C}^d$ with coordinates
	\begin{align*}
		\psi'_j:=\frac{X'_{0,j}-X'_{1,j}}{|\bar{\psi}_j|}, \qquad
		\psi''_j:=\frac{X''_{0,j}-X''_{1,j}}{|\bar{\psi}_j|},
	\end{align*}
	where $X',X''\in\{0,1\}^{2d}$ denote the indicator of the measurements outcomes $\ket{b}\ket{\bar{0}}\ket{j}$ for the states $\ket{\varphi'}$ and $\ket{\varphi''}$, respectively. 
	Then by \Cref{lem:UnbiasedTomoMeas} and the discussion after the proof of \Cref{lem:UnbiasedTomoMeas}, $\psi', \psi''$ are unbiased estimators of $\psi^{\Re}_j:=\mathrm{Re}\left(\psi_j\frac{\bar{\psi}^*_j}{|\bar{\psi}_j|}\right)$, and 
	$\psi^{\Im}_j:=\mathrm{Im}\left(\psi_j\frac{\bar{\psi}^*_j}{|\bar{\psi}_j|}\right)$ respectively,
	such that $\nrm{\psi'}_2,\nrm{\psi''}_2\leq \sqrt{d}/\eps$ with certainty and 
	\begin{align}\label{eq:covPsis}
		\mathrm{Cov}(\psi')+\mathbb{E}[\psi']\mathbb{E}[\psi'^T]\preceq \left(\frac{1}{2}+\frac{1}{2\eta}\right)I, \quad
		\mathrm{Cov}(\psi'')+\mathbb{E}[\psi'']\mathbb{E}[\psi''^T]
		\preceq \left(\frac{1}{2}+\frac{1}{2\eta}\right)I,
	\end{align}
 where for the latter psd inequalities we used that $|\bar{\psi}_j|^2\geq\eta|\psi_j|^2$ and hence $\mathrm{diag}\Big(\frac{|\psi_i|^2}{2|\bar{\psi_i|}^2}\Big)\preceq \frac{1}{2\eta}I$.

	 Let $w\in \mathbb{R}^d$, then the random variables $\psi'_w:=\braket{\psi'|w},\psi''_w:=\braket{\psi''|w}$ satisfy $|\psi'_w|\leq \nrm{\psi'}_2\nrm{w}_2\leq \sqrt{d}\nrm{w}_2/\eps$, $|\psi''_w|\leq \nrm{\psi''}_2\nrm{w}_2\leq \sqrt{d}\nrm{w}_2/\eps$ with certainty. Also, $\mathbb{E}[|\psi'_w|^2]$ and $\mathbb{E}[|\psi''_w|^2]$ are both $\leq \left(\frac{1}{2}+\frac{1}{2\eta}\right)\nrm{w}_2^2$, because for both $\phi=\psi'$ and $\phi=\psi''$, we have
	\begin{align*}
		\mathbb{E}[|\braket{\phi|w}|^2]
  =\bra{w}\mathbb{E}[\phi \phi^T]\ket{w}
		=\bra{w}(\mathrm{Cov}(\phi)+\mathbb{E}[\phi]\mathbb{E}[\phi^T])\ket{w}
		\le\nrm{\mathrm{Cov}(\phi)+\mathbb{E}[\phi]\mathbb{E}[\phi^T]}\cdot\nrm{w}_2^2.
	\end{align*}
	Let $\Psi',\Psi''\in\mathbb{R}^d$ be the sum of $n$ i.i.d.\ copies of $\psi',\psi''$, respectively, obtained from the measurement outcomes of the $n$ copies of $\ket{\varphi'}$ and $\ket{\varphi''}$, so that 
	\begin{align}\label{eq:ImReDecomp}
		\tilde{\psi}_j=(\Psi'_j+i\Psi''_j)\frac{\bar{\psi}_j}{n|\bar{\psi}_j|}.
	\end{align}
	Let us analogously define $\Psi'_w:=\braket{\Psi'|w}$, and $\Psi''_w:=\braket{\Psi''|w}$. Then clearly $\mathbb{E}[\Psi'_w]=n\braket{\psi^\Re|w}$, and $\mathbb{E}[\Psi''_w]=n\braket{\psi^\Im|w}$. 
    For all $\tau\geq 1$, the Bennett-Bernstein tail bound (\Cref{prop:BennettB}) implies
    \begin{align}\label{eq:BBCor}
		\Pr\left[|\Psi'_w-n\braket{\psi^\Re|w}|\geq \tau\frac{\eps n \nrm{w}_2}{2\sqrt{d}}\right]
		&\leq2\exp\left(-\frac{\tau^2\eps^2 n^2 \nrm{w}_2^2/(4d)}{\left(1+\frac{1}{\eta}\right)\nrm{w}_2^2 n+\frac{\tau}{3}\nrm{w}_2^2 n}\right)\nonumber\\&
		\leq2\exp\left(-\tau\frac{\eps^2 n/(4d)}{\frac{4}{3}+\frac{1}{\eta}}\right)
		\leq 2\left(\frac{\delta}{8k}\right)^{\!\!\tau},
	\end{align}
	and similarly $\Pr[|\Psi''_w-n\braket{\psi^\Im|w}|\geq \tau\eps n \nrm{w}_2/\sqrt{4d}]\leq 2\left(\frac{\delta}{8k}\right)^{\!\tau}$.

	Let $\tilde{v}_j:=v_j\frac{\bar{\psi}_j^*}{|\bar{\psi}_j|}$, $\tilde{v}^\Re_j:=\mathrm{Re}(\tilde{v}_j)$, $\tilde{v}^\Im_j:=\mathrm{Im}(\tilde{v}_j)$, and observe that for any $v\in V$ 
	\begin{align*}
		&\braket{\tilde{\psi}|v} -\braket{\psi|v}
		=\frac{1}{n}\braket{\Psi'+i\Psi''|\tilde{v}}-\braket{\psi^\Re+i\psi^\Im|\tilde{v}}\\&
		\kern6mm=\!\Bigg(\underset{:= a\nrm{\tilde{v}^\Re}_2}{\underbrace{\frac{\braket{\Psi'|\tilde{v}^\Re}}{n}-\braket{\psi^\Re|\tilde{v}^\Re}}}\underset{ := b\nrm{\tilde{v}^\Im}_2}{\underbrace{-\frac{\braket{\Psi''|\tilde{v}^\Im}}{n}+\braket{\psi^\Im|\tilde{v}^\Im}}}\!\Bigg)
		+i\Bigg(\underset{:= c\nrm{\tilde{v}^\Re}_2}{\underbrace{\frac{\braket{\Psi'|\tilde{v}^\Im}}{n}-\braket{\psi^\Re|\tilde{v}^\Im}}}\underset{ := d\nrm{\tilde{v}^\Im}_2}{\underbrace{-\frac{\braket{\Psi''|\tilde{v}^\Re}}{n}+\braket{\psi^\Im|\tilde{v}^\Re}}}\Bigg),
	\end{align*}
	so 
	\begin{align*}
		|\braket{\tilde{\psi}|v}-\braket{\psi|v}|
		&\leq \sqrt{2}\max\left\{\left|\mathrm{Re}(\braket{\tilde{\psi}|v}-\braket{\psi|v})\right|,\left|\mathrm{Im}(\braket{\tilde{\psi}|v}-\braket{\psi|v})\right|\right\}\\&
        = \sqrt{2}\max\left\{\left|a\nrm{\tilde{v}^\Re}_2+b\nrm{\tilde{v}^\Im}_2\right|,\left|c\nrm{\tilde{v}^\Re}_2+d\nrm{\tilde{v}^\Im}_2\right|\right\}\\&
		\leq \sqrt{2}\max\{|a|,|b|,|c|,|d|\}(\nrm{\tilde{v}^\Re}_2+\nrm{\tilde{v}^\Im}_2)\\&
		\leq 2\max\{|a|,|b|,|c|,|d|\}\nrm{v}_2,
	\end{align*}
	where the last step uses that $|\tilde{v}_j|=|v_j|$ for all $j$, and Cauchy-Schwarz. Using Eq.~\eqref{eq:BBCor} four times with different choices of~$w$ , and the union bound over 4 events, we have $\max\{|a|,|b|,|c|,|d|\}< \frac{\tau\eps }{2\sqrt{d}}$ except with probability $\leq 8\left(\frac{\delta}{8k}\right)^{\!\tau}$. Eq.~\eqref{eq:InnerConcentration} now follows by choosing $\tau=1$ and taking the union bound over all $k$ vectors $v\in V$. If $k\geq d$ then we can apply the statement for a set $V$ containing the computational basis, and then $\nrm{\tilde{\psi}-\psi}_\infty\leq \frac{\eps }{\sqrt{d}}$ implies $\nrm{\tilde{\psi}-\psi}_2\leq \eps$ by Cauchy-Schwarz. 

\medskip

    Now we prove the second part of \Cref{thm:UnbiasedTomoMeas}, where $V$ is an orthonormal set (the ``Finally'' part). Note that the previous paragraph already proved that for every $v\in\mathbb{C}^d$ and for all $\tau\geq 1$, 
    \begin{equation}
    \Pr[|\braket{v|\tilde{\psi}-\psi}|> \tau{\frac{\eps}{\sqrt{d}}}\nrm{v}_2]\leq 8\left(\frac{\delta}{8k}\right)^{\!\!\tau}. \label{eq:inprodconcentration}
    \end{equation}
    Defining $\mathring{\eps}:=\eps/\sqrt{d}$ and $\mathring{\psi}^{j}:=\braket{v^{(j)}|\tilde{\psi}-\psi}$, we bound
    \begin{align}
        \mathbb{E}\left[|\mathring{\psi}^{j}|\mathds{1}_{(\mathring{\eps},\infty)}(|\mathring{\psi}^{j}|)\right]\!
        &=\sum_{\ell=0}^\infty\mathbb{E}\left[|\mathring{\psi}^{j}|\mathds{1}_{(2^\ell\mathring{\eps},2^{\ell+1}\mathring{\eps}]}(|\mathring{\psi}^{j}|)\right]        \leq \sum_{\ell=0}^\infty2^{\ell+1}\mathring{\eps}\Pr\left[|\mathring{\psi}^{j}|\in(2^\ell\mathring{\eps},2^{\ell+1}\mathring{\eps}]\right]\kern25mm\nonumber\\&
        \leq \sum_{\ell=0}^\infty2^{\ell+1}\mathring{\eps}\Pr\left[|\mathring{\psi}^{j}|> 2^\ell\mathring{\eps}\right]        \leq \sum_{\ell=0}^\infty2^{\ell+1}\mathring{\eps}\,8\left(\frac{\delta}{8k}\right)^{\!\!2^\ell}\!\!\!\!\tag*{$\left(\!\Pr[|\mathring{\psi}^{j}|> \tau\mathring{\eps}]\leq 8\left(\frac{\delta}{8k}\right)^{\!\!\tau}\right)$\!}\nonumber\\&
        \leq \sum_{\ell=0}^\infty2^{\ell+1}\mathring{\eps}\,8\left(\frac{\delta}{8k}\right)^{\!\!\ell+1}\tag*{(since $\delta/k\leq 1$, and $2^\ell\geq \ell+1$)}\nonumber\\&
        = 2\frac{\delta\eps}{k\sqrt{d}} \sum_{\ell=0}^\infty\left(\frac{\delta}{4k}\right)^{\!\!\ell}        \leq 2\frac{\delta\eps}{k\sqrt{d}} \sum_{\ell=0}^\infty\left(\frac{1}{4}\right)^{\!\!\ell}\tag*{(since $\delta/k\leq 1$)}\nonumber\\&     
        < \frac{3\delta}{k} \frac{\eps}{\sqrt{d}}.\label{eq:expBound}
    \end{align}
    We have already proven Eq.~\eqref{eq:InnerConcentration}, implying that $p=\Pr[A]\leq \delta$.
    Observe that 
    \[
    \mathbb{E}[\braket{v^{(j)}|\tilde{\psi}}|A\cup (X_\zeta=0)]=\braket{v^{(j)}|\psi}+\mathbb{E}[\mathring{\psi}^{j}|A\cup (X_\zeta=0)], 
    \]
    and hence
    \[
    \mathbb{E}[\braket{v^{(j)}|\tilde{\psi}-\psi}|A\cup (X_\zeta=0)] = \mathbb{E}[\mathring{\psi}^{j}|A\cup (X_\zeta=0)].
    \]
    Since $\Pr[A\cup (X_\zeta=0)]=1-\Pr[\bar{A}\cap (X_\zeta=1)]=\delta$, using \eqref{eq:expBound} we have 
    \begin{align}\label{eq:exDev}
        |\mathbb{E}[\mathring{\psi}^{j}|A\cup (X_\zeta=0)]|
        \leq \mathbb{E}[|\mathring{\psi}^{j}|\mid A\cup (X_\zeta=0)]
        = \frac{\mathbb{E}[|\mathring{\psi}^{j}|\mathds{1}_{A\cup (X_\zeta=0)}]}{\delta}
        \leq \frac{\mathring{\eps}\delta+\frac{3\delta}{k} \frac{\eps}{\sqrt{d}}}{\delta}
        =\left(1+\frac{3}{k}\right) \frac{\eps}{\sqrt{d}}.
    \end{align}
    Since we modified $\tilde{\psi}$ on an event of probability $\delta$ to get $\widecheck{\psi}$, the total variation distance between the distributions of the random variables $\widecheck{\psi}$ and $\tilde{\psi}$ is at most $\delta$. The boundedness of~$\widecheck{\psi}$ is by construction and the unbiasedness is inherited from that of $\tilde{\psi}$, as follows: abbreviating the event $\bar{A}\cap (X_\zeta=1)$ to $B$, we have
    \begin{align*}
    \Exp[\widecheck{\psi}]& =\Pr[B]\cdot \Exp[\widecheck{\psi}\mid B] + \Pr[\bar{B}]\cdot \Exp[\widecheck{\psi}\mid \bar{B}]\\
   & =\Pr[B]\cdot \Exp[\tilde{\psi}\mid B] + \Pr[\bar{B}]\cdot \Exp[(I-\Pi_k)\tilde{\psi}+ \sum\limits_{j\in[k]}\ket{v^{(j)}}\mathbb{E}[\braket{v^{(j)}|\tilde{\psi}}]\mid \bar{B}]\\
      & =\Pr[B]\cdot \Exp[\tilde{\psi}\mid B] + \Pr[\bar{B}]\cdot \Exp[(I-\Pi_k)\tilde{\psi}+ \sum\limits_{j\in[k]}\ket{v^{(j)}}\bra{v^{(j)}}\cdot\tilde{\psi}\mid \bar{B}]\\
            & =\Pr[B]\cdot \Exp[\tilde{\psi}\mid B] + \Pr[\bar{B}]\cdot \Exp[(I-\Pi_k)\tilde{\psi}+ \Pi_k\tilde{\psi}\mid \bar{B}]\\
   &  =\Pr[B]\cdot \Exp[\tilde{\psi}\mid B] + \Pr[\bar{B}]\cdot \Exp[\tilde{\psi}\mid \bar{B}]=\Exp[\tilde{\psi}]=\psi.
\end{align*}
    Finally, defining $\bar{\eps}:=\eps\sqrt{\frac{k}{d}}$  and $\mathring{\psi}:=\Pi_k(\tilde{\psi}-\psi)=\sum_{j\in[k]}\mathring{\psi}^{j}v^{(j)}$ we bound
    \begin{align}
    \norm{\mathbb{E}\left[\ketbra{\mathring{\psi}}{\mathring{\psi}}\mathds{1}_{(\bar{\eps},\infty)}(\nrm{\mathring{\psi}}_2)\right]}
        &\leq\mathbb{E}\left[\nrm{\mathring{\psi}}_2^2\mathds{1}_{(\bar{\eps},\infty)}(\nrm{\mathring{\psi}}_2)\right]
        =\sum_{\ell=0}^\infty\mathbb{E}\left[\nrm{\mathring{\psi}}_2^2\mathds{1}_{(2^\ell\bar{\eps},2^{\ell+1}\bar{\eps}]}(\nrm{\mathring{\psi}}_2)\right]\nonumber\\&
        \leq \sum_{\ell=0}^\infty4^{\ell+1}\bar{\eps}^2\Pr\left[\nrm{\mathring{\psi}}_2\in(2^\ell\bar{\eps},2^{\ell+1}\bar{\eps}]\right]        \leq \sum_{\ell=0}^\infty4^{\ell+1}\bar{\eps}^2\Pr\left[\nrm{\mathring{\psi}}_2> 2^\ell\bar{\eps}\right]\nonumber\\&
        \leq \sum_{\ell=0}^\infty4^{\ell+1}\bar{\eps}^2 8k\left(\frac{\delta}{8k}\right)^{\!\!2^\ell}\tag*{$\left(\Pr[\nrm{\mathring{\psi}}_2> \tau\bar{\eps}]\leq 8k\left(\frac{\delta}{8k}\right)^{\!\tau}\right)$}\nonumber\\&
        \leq \sum_{\ell=0}^\infty4^{\ell+1}\bar{\eps}^28k\left(\frac{\delta}{8k}\right)^{\!\!\ell+1}\tag*{(since $\delta/k\leq 1$, and $2^\ell\geq \ell+1$)}\nonumber\\&
        = 4\delta\eps^2\frac{k}{d} \sum_{\ell=0}^\infty\left(\frac{\delta}{2k}\right)^{\!\!\ell}        \leq 4\delta\eps^2\frac{k}{d} \sum_{\ell=0}^\infty\left(\frac{1}{2}\right)^{\!\!\ell}\tag*{(since $\delta/k\leq 1$)}\nonumber\\&
        = 8\delta\eps^2\frac{k}{d}.\label{eq:SqDev}
    \end{align}
    This then implies that 
    \begin{align}
        \norm{\mathrm{Cov}(\Pi_k\tilde{\psi})-\mathrm{Cov}(\Pi_k\widecheck{\psi})}
        &=\norm{\mathbb{E}\left[\ketbra{\mathring{\psi}}{\mathring{\psi}}-\Pi_k\ketbra{\widecheck{\psi}-\psi}{\widecheck{\psi}-\psi}\Pi_k\right]}\nonumber \\&
        =\norm{\mathbb{E}\left[\left(\ketbra{\mathring{\psi}}{\mathring{\psi}}-\Pi_k\ketbra{\widecheck{\psi}-\psi}{\widecheck{\psi}-\psi}\Pi_k\right)\mathds{1}_{A\cup (X_\zeta=0)}\right]}\nonumber \\&
        \leq \norm{\mathbb{E}\left[\ketbra{\mathring{\psi}}{\mathring{\psi}}\mathds{1}_{A\cup (X_\zeta=0)}\right]}
        +\norm{\mathbb{E}\left[\Pi_k\ketbra{\widecheck{\psi}-\psi}{\widecheck{\psi}-\psi}\Pi_k\cdot \mathds{1}_{A\cup (X_\zeta=0)}\right]}\label{eq:CovTriangle}, 
    \end{align}    
       where the second equality is because $\tilde{\psi}=\widecheck{\psi}$ on the complement of the event $A\cup (X_\zeta=0)$.
       Using the definition of $\widecheck{\psi}$, and the fact that $\Pi_k(I-\Pi_k)=0$, we can see that $\Pi_k\widecheck{\psi}$ conditioned on $A\cup (X_\zeta=0)$ is actually a fixed vector $\mathbb{E}[\Pi_k\tilde{\psi}\mid A\cup (X_\zeta=0)]$, not a random variable anymore.
       We now have
       \[
       \norm{\mathbb{E}\left[\Pi_k\ketbra{\widecheck{\psi}-\psi}{\widecheck{\psi}-\psi}\Pi_k\cdot \mathds{1}_{A\cup (X_\zeta=0)}\right]}=\Pr[A\cup (X_\zeta=0)]\cdot\norm{\mathbb{E}\left[\Pi_k\ket{\tilde{\psi}-\psi}\mid {A\cup (X_\zeta=0)}\right]}^2_2.
       \]
       Continuing with Eq.~\eqref{eq:CovTriangle}, we have
     \begin{align*}  
     \hspace*{-0.8em}\norm{\mathrm{Cov}(\Pi_k\tilde{\psi})-\mathrm{Cov}(\Pi_k\widecheck{\psi})}
     &\leq\norm{\mathbb{E}\left[\ketbra{\mathring{\psi}}{\mathring{\psi}}\mathds{1}_{A\cup (X_\zeta=0)}\right]}+\delta \nrm{\mathbb{E}[\mathring{\psi}\mid A\cup (X_\zeta=0)]}_2^2\\&
        \leq\mathbb{E}\left[\nrm{\mathring{\psi}}_2^2\mathds{1}_{A\cup (X_\zeta=0)}\right]
        +16\delta\eps^2\frac{k}{d}\tag{by \eqref{eq:exDev} and $(1+3/k\leq4)$}\\&
        =  \mathbb{E}\left[\nrm{\mathring{\psi}}_2^2\mathds{1}_{A\cup (X_\zeta=0)}\Big(\mathds{1}_{[0,\bar{\epsilon}]}(\nrm{\mathring{\psi}}_2)+\mathds{1}_{(\bar{\eps},\infty)}(\nrm{\mathring{\psi}}_2)\Big)\right]
        +16\delta\eps^2\frac{k}{d}   \\&
        \leq \delta\bar{\eps}^2+8\delta\eps^2\frac{k}{d}+16\delta\eps^2\frac{k}{d}=25\delta\eps^2\frac{k}{d}.\tag*{(by \eqref{eq:SqDev} and $\Pr[A\cup (X_\zeta=0)]=\delta$)}
    \end{align*}  
We obtain 
\[
\norm{\mathrm{Cov}(\Pi_k\widecheck{\psi})} \leq  \norm{\mathrm{Cov}(\Pi_k\tilde{\psi})-\mathrm{Cov}(\Pi_k\widecheck{\psi})}+\norm{\mathrm{Cov}(\Pi_k\tilde{\psi})} \leq 25\delta\eps^2\frac{k}{d}+ \frac{\eps^2}{4d\ln\left(\frac{8k}{\delta}\right)}
\]
because $\norm{\mathrm{Cov}(\Pi_k\tilde{\psi})}\leq \norm{\mathrm{Cov}(\tilde{\psi})}=\frac{1}{n}\norm{\mathrm{Cov}(\psi')+\mathrm{Cov}(\psi'')}$, and the matrix inside the latter norm can be upper bounded by $2(\frac{1}{2}+\frac{1}{2\eta})I$ using Eq.~\eqref{eq:covPsis}.
\end{proof}
